/**
 * Prediction / forecast data for the service centre.
 * Generated by a future prediction engine; mocked for now.
 */
export interface PredictionSnapshot {
  /** Predicted total footfall for today (full day) */
  predictedFootfallToday: number;
  /** Predicted hourly footfall: index = hour (0-23) */
  predictedHourlyFootfall: number[];
  /** Predicted average wait time in seconds for upcoming hours */
  predictedAvgWaitSec: number[];
  /** Predicted queue load per service: serviceId → predicted waiting count */
  predictedQueueLoad: Record<string, number>;
}
